ROOT = Path(__file__).resolve().parent.parent
CACHE = ROOT / "raw/cache/relevance"
UA = "Mozilla/5.0 (research script)"

class PageText(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.skip = 0
        self.in_title = False
        self.title = []
        self.meta = []
        self.text = []
    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if tag in ("script", "style", "noscript", "svg", "template"):
            self.skip += 1
        if tag == "title": self.in_title = True
        if tag == "meta" and (a.get("name", "").lower() == "description" or a.get("property", "").lower() == "og:description"):
            self.meta.append(a.get("content", ""))
    def handle_endtag(self, tag):
        if tag in ("script", "style", "noscript", "svg", "template"):
            self.skip = max(0, self.skip - 1)
        if tag == "title": self.in_title = False
    def handle_data(self, data):
        if self.in_title: self.title.append(data)
        elif not self.skip and data.strip(): self.text.append(data.strip())

RATE_LOCK = threading.Lock()
NEXT_REQUEST = 0.0

def request_slot():
    global NEXT_REQUEST
    with RATE_LOCK:
        time.sleep(max(0, NEXT_REQUEST - time.monotonic()))
        NEXT_REQUEST = time.monotonic() + 1.0

class PoliteHTTP(HTTPHandler):
    def http_open(self, request):
        request_slot()
        return super().http_open(request)

class PoliteHTTPS(HTTPSHandler):
    def https_open(self, request):
        request_slot()
        return super().https_open(request)

def fetch(url, retry_errors=False):
    CACHE.mkdir(parents=True, exist_ok=True)
    key = hashlib.sha1(url.encode()).hexdigest()
    target = CACHE / (key + ".json")
    previous = json.loads(target.read_text(encoding="utf-8")) if target.exists() else None
    if previous and (not previous["error"] or not retry_errors): return previous
    result = {"url": url, "title": "", "meta": "", "text": "", "error": "",
              "checked_at_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
              "attempts": []}
    if previous:
        result["previous_attempt"] = previous
    opener = build_opener(PoliteHTTP(), PoliteHTTPS())
    # The protocol handlers also rate-limit redirects. Timeouts are 15 seconds.
    # Retry transient HTTP/network errors once, with exponential backoff.
    for attempt in range(2):
        content = None
        transient = False
        try:
            with opener.open(Request(url, headers={"User-Agent": UA}), timeout=15) as response:
                body = response.read(2_000_000)
                charset = response.headers.get_content_charset() or "utf-8"
                content = body.decode(charset, errors="replace")
                result.update(final_url=response.url, status=response.status,
                              content_type=response.headers.get("Content-Type", ""), error="")
        except HTTPError as exc:
            result.update(status=exc.code, final_url=exc.url, error=str(exc))
            transient = exc.code == 429 or exc.code >= 500
            try:
                content = exc.read(2_000_000).decode(exc.headers.get_content_charset() or "utf-8", errors="replace")
            except Exception:
                pass
        except Exception as exc:
            result["error"] = str(exc)
            reason = getattr(exc, "reason", exc)
            transient = not isinstance(reason, ssl.SSLError)
        result["attempts"].append({"error": result["error"], "status": result.get("status")})
        if content is not None:
            (CACHE / (key + ".html")).write_text(content, encoding="utf-8")
            parser = PageText()
            parser.feed(content)
            result.update(title=" ".join(parser.title), meta=" ".join(parser.meta),
                          text=" ".join(parser.text)[:18000])
        if not result["error"] or not transient or attempt == 1: break
        time.sleep(2 ** (attempt + 1))
    target.write_text(json.dumps(result, ensure_ascii=False, indent=2), encoding="utf-8")
    return result

def rows():
    result = []
    # Original task snapshot: 983 dated rows across these ten supplied files.
    # cohort_short.csv appeared during execution and duplicates original records.
    filenames = ("baystartup", "cyberlab", "falling_walls", "hightechxl",
                 "kit_gruenderschmiede", "science4life", "sib", "spinlab", "unikat", "utum")
    for name in filenames:
        path = ROOT / "raw" / ("cohort_" + name + ".csv")
        retained = 0
        with path.open(encoding="utf-8-sig", newline="") as handle:
            for row in csv.DictReader(handle):
                if not row.get("asof_date", "").strip(): continue
                row["_file"] = path.stem.removeprefix("cohort_")
                row["_index"] = retained
                retained += 1
                result.append(row)
    return result

