def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--fetch", action="store_true")
    ap.add_argument("--retry-errors", action="store_true", help="Retry cached unsuccessful homepages")
    args = ap.parse_args()
    data = rows()
    if args.fetch:
        urls = sorted({r["website"].strip() for r in data if needs_homepage(r)})
        with ThreadPoolExecutor(max_workers=12) as pool:
            jobs = {pool.submit(fetch, u, args.retry_errors): u for u in urls}
            results = []
            for future in as_completed(jobs):
                p = future.result()
                results.append(p)
                if len(results) % 25 == 0: print("Homepage research:", len(results), "/", len(urls), flush=True)
            print("Cached homepages:", len(results), "Errors:", sum(bool(p["error"]) for p in results))
        return
    codes = {"D": "deep_tech", "S": "digital_tech", "L": "life_science", "N": "non_tech", "U": "unclear"}
    output = []
    for r in data:
        token, reason = DECISIONS[row_key(r)]
        category = codes[token.rstrip("?")]
        relevant = "maybe" if token.endswith("?") or category == "unclear" else "no" if category == "non_tech" else "yes"
        assert len(reason.split()) <= 12, (r["name"], reason)
        used = needs_homepage(r)
        if used:
            cache = CACHE / (hashlib.sha1(r["website"].strip().encode()).hexdigest() + ".json")
            assert cache.exists(), ("Missing homepage research", r["name"])
        output.append({**{k: r[k] for k in ("source", "name", "website", "asof_date")},
                       "category": category, "htgf_relevant": relevant, "reason": reason,
                       "used_website": int(used)})
    assert set(DECISIONS) == {row_key(r) for r in data}, "Input rows changed since review"
    assert len(output) == 983, len(output)
    dest = ROOT / "raw/relevance_v2.csv"
    with dest.open("w", encoding="utf-8", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=list(output[0]))
        writer.writeheader()
        writer.writerows(output)
    groups = {"OVERALL": output}
    for source in sorted({r["source"] for r in output}):
        groups[source] = [r for r in output if r["source"] == source]
    for source, group in groups.items():
        categories = Counter(r["category"] for r in group)
        relevance = Counter(r["htgf_relevant"] for r in group)
        print(source, "rows=", len(group), "category=", {c: categories[c] for c in codes.values()},
              "htgf_relevant=", {v: relevance[v] for v in ("yes", "maybe", "no")})
    print("Website checks:", sum(r["used_website"] for r in output))
    print("Missing percentages:", {k: round(100 * sum(not str(r[k]).strip() for r in output) / len(output), 2) for k in output[0]})
    print("10 random examples (seed 42):")
    for r in random.Random(42).sample(output, 10): print(json.dumps(r, ensure_ascii=False))

if __name__ == "__main__": main()
